def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    out = [row[:] for row in grid]

    # Group adjacent non-background rows into horizontal pattern bands.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        bands.append((start, r))

    # Repeated multi-row bands: copy the missing right-hand part of the
    # fuller band into its matching, horizontally shifted counterpart.
    for i in range(len(bands)):
        a0, a1 = bands[i]
        ha = a1 - a0
        if ha < 2:
            continue
        for j in range(i + 1, len(bands)):
            b0, b1 = bands[j]
            if b1 - b0 != ha:
                continue

            ca = sum(v != bg for row in grid[a0:a1] for v in row)
            cb = sum(v != bg for row in grid[b0:b1] for v in row)
            if ca == cb:
                continue

            if ca > cb:
                src0, tgt0 = a0, b0
                src_count, tgt_count = ca, cb
            else:
                src0, tgt0 = b0, a0
                src_count, tgt_count = cb, ca

            # The shorter band is the incomplete target; only complete its
            # region to the right of its existing pattern.
            boundary = max(
                c
                for rr in range(tgt0, tgt0 + ha)
                for c, v in enumerate(grid[rr])
                if v != bg
            )

            best = None
            for shift in range(-w + 1, w):
                matches = total = covered = target_pixels = 0
                for k in range(ha):
                    src = grid[src0 + k]
                    tgt = grid[tgt0 + k]
                    for c in range(boundary + 1):
                        sc = c - shift
                        if not 0 <= sc < w:
                            continue
                        sf = src[sc] != bg
                        tf = tgt[c] != bg
                        total += 1
                        matches += (sf == tf)
                        if tf:
                            target_pixels += 1
                            covered += sf

                if total == 0 or target_pixels == 0:
                    continue
                agreement = matches / total
                coverage = covered / target_pixels
                score = (agreement, coverage, -abs(shift))
                if best is None or score > best[0]:
                    best = (score, shift)

            if best is None or best[0][0] < 0.72 or best[0][1] < 0.75:
                continue

            shift = best[1]
            for k in range(ha):
                src = grid[src0 + k]
                tgt_r = tgt0 + k
                for sc in range(w):
                    c = sc + shift
                    if boundary < c < w and src[sc] != bg and grid[tgt_r][c] == bg:
                        out[tgt_r][c] = 1

    # Isolated single-row bars extend to the right; if already touching the
    # edge, mark their terminal foreground run instead.
    for start, end in bands:
        if end - start != 1:
            continue
        r = start
        row = grid[r]
        if all(v != bg for v in row):
            continue
        right = max(c for c, v in enumerate(row) if v != bg)
        if right < w - 1:
            for c in range(right + 1, w):
                out[r][c] = 1
        else:
            c = w - 1
            color = row[c]
            while c >= 0 and row[c] == color:
                out[r][c] = 1
                c -= 1

    return out
